namespace ghidra.app.cmd.label;



using ghidra.app.util.demangler;
using ghidra.framework.cmd;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util;
using ghidra.util.classfinder;
using ghidra.util.task;

public class DemanglerCmd : BackgroundCommand<Program> {

	private Address addr;
	private string mangled;
	private string result;
	private DemangledObject demangledObject;
	private static List<Demangler> demanglers;
	private DemanglerOptions options;

	public DemanglerCmd(Address addr, string mangled) : this(addr, mangled, new DemanglerOptions())
    {
	}

	public DemanglerCmd(Address addr, string mangled, DemanglerOptions options) : base("Demangle Symbol", false, true, false)
    {
		this.addr = addr;
		// Remove any @Address that is appended to the name.
		this.mangled = SymbolUtilities.getCleanSymbolName(mangled, addr);
		this.options = options;
	}

	/* @Override */
	public bool applyTo(Program prog, TaskMonitor monitor) {

		// search until we find a demangler that can handle the given mangled input
		foreach (Demangler demangler in getDemanglers()) {
			if (!demangler.canDemangle(prog)) {
				continue;
			}

			if (!doDemangle(demangler, prog, monitor)) {
				return false; // some kind of error
			}

			if (result != null) {
				return true; // successful; don't try a different demangler
			}
		}

		return false;
	}

	private bool doDemangle(Demangler demangler, Program program, TaskMonitor monitor) {

		MangledContext mangledContext =
			demangler.createMangledContext(mangled, options, program, addr);
		try {
			demangledObject = demangler.demangle(mangledContext);
		}
		catch (DemangledException e) {
			if (e.isInvalidMangledName()) {
				//ignore invalid names, consider as not an error
				setStatusMsg("Invalid mangled name");
				return true; // no real error
			}

			setStatusMsg("Unable to demangle symbol: " + mangled + " at " + addr + ".  Message: " +
				e.getMessage());
			return false; // error

			// This produces too many messages for non-demangled symbols.  If we could
			// figure out a way to tell which symbol are those which are mangled and
			// failing, then we should print those.  The problem is not knowing how to
			// tell a mangled from a non-mangled symbol.
			// Msg.debug(this, "Unable to demangle name: " + mangled);
		}
		catch (Exception e) {
			// Demangler IndexOutOfBoundsException that we're not sure how to fix
			setStatusMsg("Unable to demangle symbol: " + mangled + " at " + addr + ". Message: " +
				e.getMessage());
			return false;
		}

		if (demangledObject == null) {
			return true; // no error
		}

		try {
			if (demangledObject.applyTo(program, addr, options, monitor)) {
				result = demangledObject.getSignature(true);
				return true;
			}
		}
		catch (Exception e) {
			updateStatusForUnexpectedException(e);
			return false;
		}

		setStatusMsg("Failed to apply mangled symbol at " + addr + "; name:  " + mangled + " (" +
			demangler.GetType().getName() + "/" + demangledObject.GetType().getName() + ")");
		return false; // error
	}

	private void updateStatusForUnexpectedException(Exception e) {
		string message = e.getMessage();
		if (message == null) {
			setStatusMsg("Unable to demangle symbol at " + addr.toString() + "; name: " + mangled +
				".  Message: " + e.toString());
		}
		else {
			setStatusMsg("Unable to demangle symbol at " + addr.toString() + "; name: " + mangled +
				".  Message: " + message);
		}

		Msg.error(this, getStatusMsg(), e);
	}

	public string getResult() {
		return result;
	}

	public DemangledObject getDemangledObject() {
		return demangledObject;
	}

	private static List<Demangler> getDemanglers() {
		if (demanglers == null) {
			demanglers = ClassSearcher.getInstances(typeof(Demangler));
		}
		return demanglers;
	}
}
